_BUDGETS = (None, None, None, 9000)


def _metrics(storage):
    return (
        storage.checkpoint_bytes,
        storage.signature_wire_bytes,
        storage.proof_wire_bytes,
        profile("merkle", w=storage.w, height=storage.height).steps,
    )


def _tail(storage):
    return (
        storage.checkpoint_bytes,
        storage.leaf_count,
        storage.w,
        storage.height,
    )


def _expected_rows(capacity, budgets, scenarios):
    """Recompute the documented per-candidate breakdown independently."""
    frontier = merkle_deployment_frontier(capacity, budgets)
    rows = [_metrics(storage) for storage in frontier]
    spans = tuple(
        (min(row[i] for row in rows), max(row[i] for row in rows))
        for i in range(4)
    )
    totals = tuple(sum(weights) for weights in scenarios)

    entries = []
    for storage, values in zip(frontier, rows):
        costs = tuple(
            Fraction(value - low, high - low) if high > low else Fraction(0)
            for value, (low, high) in zip(values, spans)
        )
        scores = tuple(
            sum(
                (weight * component for weight, component in zip(weights, costs)),
                Fraction(0),
            )
            / total
            for weights, total in zip(scenarios, totals)
        )
        entries.append((storage, costs, scores))

    best = tuple(
        min(entry[2][scenario_index] for entry in entries)
        for scenario_index in range(len(scenarios))
    )
    entries = [
        (
            storage,
            costs,
            scores,
            tuple(score - floor for score, floor in zip(scores, best)),
        )
        for storage, costs, scores in entries
    ]

    def key(entry):
        storage, _costs, scores, regrets = entry
        return (
            max(regrets),
            sum(regrets, Fraction(0)),
            scores,
            *_tail(storage),
        )

    chosen = min(entries, key=key)[0]
    return tuple(
        MerkleDeploymentScenarioScore(
            storage, *costs, scores, regrets, storage == chosen
        )
        for storage, costs, scores, regrets in entries
    )


